effect.shader:
float hash(vec2 p) {
  return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}

float smoothNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f); 
  float bottom = mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x);
  float top = mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x);
  return mix(bottom, top, f.y);
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  vec2 shift = vec2(100.0);
  for (int i = 0; i < 3; ++i) {
    v += a * smoothNoise(p);
    p = p * 2.0 + shift;
    a *= 0.5;
  }
  return v;
}

float gray(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }

void main(){
  vec2 uv = acScreenNorm;

  vec4 srcSample = texture2DCv(inputImg.texture, uv);
  float srcLuma = gray(srcSample.rgb);

  vec2 noiseUV = uv * noiseFreq;
  float blobs = fbm(noiseUV);

  float combinedVal = (srcLuma * sourceScale) + blobs;

  vec3 freqRGB = vec3(1.0, 1.15, 1.3); 
  vec3 phaseRGB = vec3(0.0, 0.33, 0.67); 

  vec3 colorPhase = (combinedVal * freqColors * freqRGB) + phaseRGB + (acTime * phaseSpeed);
  vec3 outCol = 0.5 + 0.5 * sin(colorPhase * 6.283185);

  float lumaOut = gray(outCol);
  outCol = mix(vec3(lumaOut), outCol, saturation);

  float outlineMask = smoothstep(0.05, 0.3 * outlineStrength, srcLuma);
  outCol *= mix(1.0, outlineMask, outlineStrength);

  vec3 finalCol = mix(outCol, srcSample.rgb, mixWithSource);
  gl_FragColor = vec4(finalCol, srcSample.a);
}
